/* Study state is local to this browser. No service credentials or live account access. */
const C=window.COURSE,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='az401-atlas-v1';
let state={labs:{},bookmarks:[],attempts:[],scenarioNotes:{},scenarioReviewed:[]};
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved&&typeof saved==='object')state={...state,...saved};}catch{}
let quiz=null,scenario=0,reveal=false,mapId='process',search='',domain='all',statusFilter='all';
const done=()=>C.labs.filter(l=>state.labs[l.id]==='done').length;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('Não foi possível guardar. Exporte uma cópia do progresso.');}updateSide();}
function updateSide(){const pct=Math.round(done()/20*100);$('#sidepct').textContent=pct+'%';$('#sidebarfill').style.width=pct+'%';$('#sidecount').textContent=done()+' de 20 laboratórios concluídos';}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function linkInline(s){return esc(s).replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{const decoded=url.replace(/&amp;/g,'&');if(!/^https?:\/\//.test(decoded))return label;return `<a href="${esc(decoded)}" target="_blank" rel="noopener">${label} ↗</a>`;}).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
function markdown(raw){let lines=raw.split('\n'),out='',i=0;while(i<lines.length){let l=lines[i];if(l.startsWith('```')){const lang=l.slice(3);let code=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))code.push(lines[i++]);out+=`<div class="codewrap"><pre><code data-language="${esc(lang)}">${esc(code.join('\n'))}</code></pre><button class="copybtn" type="button">Copiar</button></div>`;i++;continue;}
if(/^#{1,4} /.test(l)){const n=l.match(/^#+/)[0].length;out+=`<h${n}>${linkInline(l.slice(n+1))}</h${n}>`;i++;continue;}
if(l.startsWith('|')){let table=[];while(i<lines.length&&lines[i].startsWith('|'))table.push(lines[i++]);out+='<div class="tablewrap"><table>';table.forEach((r,n)=>{if(/^\|[\s:|–-]+\|$/.test(r))return;const tag=n===0?'th':'td';out+='<tr>'+r.split('|').slice(1,-1).map(c=>`<${tag}>${linkInline(c.trim())}</${tag}>`).join('')+'</tr>';});out+='</table></div>';continue;}
if(/^\d+\. |^- /.test(l)){const ordered=/^\d+\./.test(l),tag=ordered?'ol':'ul';out+=`<${tag}>`;while(i<lines.length&&(ordered?/^\d+\. /:/^- /).test(lines[i]))out+='<li>'+linkInline(lines[i++].replace(/^(\d+\.|-) /,''))+'</li>';out+=`</${tag}>`;continue;}
if(!l.trim()){i++;continue;}let p=[l];i++;while(i<lines.length&&lines[i].trim()&&!/^(#|```|\||\d+\. |\- )/.test(lines[i]))p.push(lines[i++]);out+='<p>'+linkInline(p.join(' '))+'</p>';}
return out;}
const statusLabel=s=>({done:'Concluído',progress:'Em estudo',simulated:'Simulado',pending:'Não iniciado'}[s]||'Não iniciado');
const groupFor=l=>C.groups.find(g=>g.id===l.domain);
function header(label,title,subtitle){return `<div class="pagehead"><div><span class="tag">${label}</span><h1>${title}</h1><p class="sub">${subtitle}</p></div></div>`;}
function home(){let next=C.labs.find(l=>state.labs[l.id]!=='done')||C.labs[0],best=state.attempts.length?Math.max(...state.attempts.map(a=>a.score)):null;
return header('SEU ESPAÇO DE ESTUDO','Construa o seu próximo passo.','Da primeira work item ao incident response. Um percurso prático para o AZ-401.')+`<section class="hero"><div><span class="eyebrow">APRENDER. APLICAR. CONECTAR.</span><h2>De DevOps a agentic DevOps.<br>Um laboratório de cada vez.</h2><p>Explore os conceitos, pratique no seu ambiente e transforme cada checkpoint em conhecimento.</p><a class="btn primary" href="#lab/${next.id}">${done()?'Continuar percurso':'Começar percurso'} <span>↗</span></a></div><div class="heroart" aria-hidden="true"><div class="orbit"><strong>AZ-401<small>DEVOPS ATLAS</small></strong><span class="orb a">⌘</span><span class="orb b">⌁</span><span class="orb c">✓</span></div></div></section><section class="stats" aria-label="Estatísticas de estudo"><div class="stat"><span>LABORATÓRIOS CONCLUÍDOS</span><strong>${done()} <small>/ 20</small></strong><small>Aprenda colocando em prática</small></div><div class="stat"><span>DOMÍNIOS DO EXAME</span><strong>05</strong><small>Conectados no mapa mental</small></div><div class="stat"><span>QUESTÕES PARA PRATICAR</span><strong>50</strong><small>40 objetivas + 10 cenários</small></div><div class="stat"><span>MELHOR RESULTADO OBJETIVO</span><strong>${best===null?'—':best+'%'}</strong><small>${state.attempts.length?state.attempts.length+' tentativa(s) concluída(s)':'Seu primeiro resultado começa aqui'}</small></div></section><div class="homegrid"><section><div class="sectionhead"><h2>Seu mapa de competências</h2><a class="link" href="#labs">Ver laboratórios ↗</a></div><div class="card">${C.groups.map((g,i)=>`<a class="domainrow" href="#domain/${g.id}"><span class="domainicon" style="--c:${g.color}">${['◎','⑂','⇄','◇','⌁'][i]}</span><div><h3>${g.name}</h3><small>${g.labs.length} laboratórios · ${g.weight} do exame</small></div><div class="dprogress">${g.labs.filter(id=>state.labs[id]==='done').length}/${g.labs.length}<div class="bar"><i style="width:${g.labs.filter(id=>state.labs[id]==='done').length/g.labs.length*100}%;background:${g.color}"></i></div></div></a>`).join('')}</div></section><section><div class="sectionhead"><h2>Conecte as ideias</h2></div><div class="card quickcard"><span class="eyebrow">UMA VISÃO DO TODO</span><div class="mapmini" aria-hidden="true"><span></span>─<b>AZ-401</b>─<span></span></div><h3>O conhecimento faz mais<br>sentido quando se conecta.</h3><p>Veja como planning, código, pipelines, segurança e observability se relacionam.</p><a href="#map" class="btn">Explorar mapa mental ↗</a></div><div class="notice">⏱ Percurso estimado: 35–50 horas.<br>As práticas usam os seus ambientes GitHub e Azure. Recursos podem exigir licença e gerar custos.</div></section></div>`;}
function labCard(l){let g=groupFor(l),s=state.labs[l.id];return `<article class="card labcard" style="--c:${g.color}"><span class="labnum">LAB ${String(l.id).padStart(2,'0')}</span><span class="status ${s==='done'?'done':''}">${statusLabel(s)}</span><h3>${l.title}</h3><p>${g.name}</p><a href="#lab/${l.id}">Abrir laboratório <span>↗</span></a></article>`;}
function labList(){return header('APRENDER NA PRÁTICA','Seu percurso, passo a passo.','20 laboratórios guiados. Conceitos, instruções e checkpoints num só lugar.')+`<div class="toolbar"><input class="search" type="search" id="labsearch" aria-label="Pesquisar laboratórios" placeholder="Pesquisar por título, conceito ou ferramenta…" value="${esc(search)}"><select id="domainfilter" aria-label="Filtrar por domínio"><option value="all">Todos os domínios</option>${C.groups.map(g=>`<option value="${g.id}" ${domain===g.id?'selected':''}>${g.name}</option>`).join('')}</select><select id="statusfilter" aria-label="Filtrar por progresso"><option value="all">Todo o progresso</option>${['pending','progress','done','simulated','saved'].map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${s==='saved'?'Favoritos':statusLabel(s)}</option>`).join('')}</select></div><p class="mini" id="resultcount"></p><div class="labgrid" id="labresults"></div>`;}
function filterLabs(){let ls=C.labs.filter(l=>(domain==='all'||l.domain===domain)&&(statusFilter==='all'||(statusFilter==='saved'?state.bookmarks.includes(l.id):(state.labs[l.id]||'pending')===statusFilter))&&(!search||l.body.toLocaleLowerCase().includes(search.toLocaleLowerCase())));$('#labresults').innerHTML=ls.map(labCard).join('')||'<div class="empty">Nenhum laboratório encontrado. Experimente outro filtro.</div>';$('#resultcount').textContent=ls.length+' laboratório(s) neste filtro';}
function labDetail(id){let l=C.labs.find(l=>l.id===id);if(!l)return header('NÃO ENCONTRADO','Laboratório indisponível.','Volte ao percurso para escolher um laboratório.');return `<div class="reading-head"><a class="link" href="#labs">← Todos os laboratórios</a><div style="display:flex;gap:10px"><button class="btn" id="bookmark" aria-pressed="${state.bookmarks.includes(id)}">${state.bookmarks.includes(id)?'★ Guardado':'☆ Guardar'}</button><select id="labstatus" aria-label="Estado do laboratório">${['pending','progress','simulated','done'].map(s=>`<option value="${s}" ${state.labs[id]===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div></div><article class="reading"><span class="tag">${groupFor(l).name} · LAB ${String(id).padStart(2,'0')}</span>${markdown(l.body)}<div class="notice">Marque como concluído apenas depois de validar os checkpoints. Uma simulação deve permanecer identificada como tal.</div></article><div class="readnav">${id>1?`<a class="btn" href="#lab/${id-1}">← Lab ${String(id-1).padStart(2,'0')}</a>`:'<span></span>'}${id<20?`<a class="btn dark" href="#lab/${id+1}">Próximo laboratório →</a>`:'<a class="btn dark" href="#quiz">Praticar questionário →</a>'}</div>`;}
function mapView(){let g=C.groups.find(g=>g.id===mapId)||C.groups[0];const pos=[[90,40],[490,40],[550,240],[290,410],[30,240]];return header('VISÃO CONECTADA','O exame, num mapa mental.','Selecione um domínio para explorar os conceitos e abrir os laboratórios relacionados.')+`<div class="maplegend">${C.groups.map(g=>`<button class="chip ${mapId===g.id?'active':''}" data-map="${g.id}">${g.name}</button>`).join('')}</div><div class="maplayout"><section class="mapcanvas"><svg class="mindmap" viewBox="0 0 800 540" role="img" aria-label="Mapa mental dos cinco domínios do exame AZ-401"><defs><pattern id="grid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#dfe6da"/></pattern></defs><rect width="800" height="540" fill="url(#grid)"/>${C.groups.map((g,i)=>{let [x,y]=pos[i];return `<path d="M400 265 Q${x+100} 265 ${x+100} ${y+47}" fill="none" stroke="${g.color}" stroke-opacity=".45" stroke-width="1.8"/>`;}).join('')}<rect x="322" y="220" width="156" height="90" rx="20" fill="#234e41"/><text x="400" y="258" text-anchor="middle" fill="#edf3df" font-family="Manrope,sans-serif" font-weight="700" font-size="23">AZ-401</text><text x="400" y="282" text-anchor="middle" fill="#b8cba7" font-size="10">AGENTIC DEVOPS</text>${C.groups.map((g,i)=>{let [x,y]=pos[i];return `<g class="node" data-map="${g.id}" role="button" tabindex="0" aria-label="Explorar ${g.name}" aria-pressed="${g.id===mapId}"><rect x="${x}" y="${y}" width="200" height="96" rx="13" stroke="${g.id===mapId?g.color:'#e2e7df'}" stroke-width="${g.id===mapId?2:1}" fill="${g.id===mapId?'#f1f5eb':'white'}"/><circle cx="${x+19}" cy="${y+22}" r="4" fill="${g.color}"/><text x="${x+31}" y="${y+26}" fill="${g.color}" font-size="10" font-weight="700">${g.weight} DO EXAME</text><text x="${x+15}" y="${y+51}" fill="#304b3b" font-size="13" font-weight="600">${g.name}</text><text x="${x+15}" y="${y+74}" fill="#82907b" font-size="10">${g.labs.length} laboratórios para explorar ↗</text></g>`;}).join('')}</svg><p class="mapcaption">Planning → code → build → deploy → operate → feedback</p></section><aside class="card mapdetail"><div><span class="tag">DOMÍNIO SELECIONADO</span><h3>${g.name}</h3><p class="mini">${g.weight} do exame · ${g.labs.length} laboratórios</p>${g.concepts.map(c=>`<div class="concept">${c}</div>`).join('')}</div><div><h4>Coloque em prática</h4>${g.labs.map(id=>`<a class="maplab" href="#lab/${id}"><span class="mini">L${String(id).padStart(2,'0')}</span> ${C.labs[id-1].title} ↗</a>`).join('')}</div></aside></div><p class="notice">Os domínios se cruzam: security acompanha a pipeline; telemetry orienta os gates; incident response fecha o ciclo no Boards. O mapa organiza o estudo e não substitui o study guide oficial.</p>`;}
function quizLanding(){return `<div class="quizintro">${header('PRATIQUE E REVISE','Transforme estudo em confiança.','Perguntas originais em inglês, baseadas nos tópicos do curso. Não são questões reais do exame.')}<div class="quizmodes"><section class="card"><span class="tag">40 MULTIPLE-CHOICE QUESTIONS</span><h3>Prática com feedback</h3><p>Responda no seu ritmo. Veja a correção e a explicação a cada pergunta. Resultado final e revisão das respostas.</p><button class="btn dark" id="startpractice">Começar prática →</button></section><section class="card"><span class="tag">40 QUESTIONS · FINAL FEEDBACK</span><h3>Simulado de estudo</h3><p>Sem mostrar o gabarito durante a tentativa. Cronómetro de tempo decorrido e correção no final. Meta didática: 80%.</p><button class="btn" id="startexam">Começar simulado →</button></section></div><section class="card"><span class="tag">10 ADDITIONAL SCENARIOS</span><h3>Decisões que pedem mais do que uma alternativa.</h3><p class="sub">Questões 41–50: escreva a sua resposta e compare com o modelo. Autoavaliação separada da pontuação objetiva.</p><button class="btn" id="startscenarios" style="margin-top:20px">Explorar cenários →</button></section><h2>Suas tentativas</h2>${state.attempts.length?state.attempts.slice().reverse().slice(0,8).map(a=>`<div class="domainrow"><span class="domainicon" style="--c:#49826c">✓</span><div><h3>${a.mode==='exam'?'Simulado':'Prática'} · ${a.correct}/40 corretas</h3><small>${new Date(a.date).toLocaleString('pt-PT')} · ${Math.round(a.seconds/60)} min</small></div><strong style="margin-left:auto">${a.score}%</strong></div>`).join(''):'<p class="sub">Ainda não há tentativas concluídas. O primeiro passo conta.</p>'}<p class="notice">A meta de 80% serve apenas para orientar o estudo. Não corresponde à escala de pontuação da Microsoft. O progresso é local e pode ser exportado.</p></div>`;}
function startQuiz(mode){quiz={mode,index:0,answers:{},checked:{},start:Date.now(),finished:false};location.hash='quiz/session';render();}
function elapsed(){let t=Math.floor((Date.now()-quiz.start)/1000);return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`;}
function quizSession(){if(!quiz)return quizLanding();if(quiz.finished)return quizResults();let q=C.questions[quiz.index],a=quiz.answers[q.id],checked=!!quiz.checked[q.id]&&quiz.mode==='practice';return `<section class="quizbox"><div class="quiztop"><a href="#quiz" class="link">← Voltar sem finalizar</a><span>${quiz.mode==='exam'?'SIMULADO':'PRÁTICA'} · <b id="timer">${elapsed()}</b></span><span>QUESTION ${quiz.index+1} OF 40</span></div><div class="bar"><i style="width:${(quiz.index+1)/40*100}%"></i></div><h1 class="question">${esc(q.prompt)}</h1><div class="options">${q.options.map((o,i)=>`<button class="option ${a===i?'selected':''} ${checked?(i===q.answer?'correct':i===a?'wrong':''):''}" data-option="${i}" ${checked?'disabled':''} aria-pressed="${a===i}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>${checked?`<div class="explain ${a!==q.answer?'error':''}"><strong>${a===q.answer?'Correct.':'Not quite.'} Answer: ${String.fromCharCode(65+q.answer)}</strong><br>${esc(q.explanation)}</div>`:''}<div class="quizactions"><button class="btn" id="prevq" ${quiz.index===0?'disabled':''}>← Previous</button>${quiz.mode==='practice'&&!checked?`<button class="btn dark" id="checkq" ${a===undefined?'disabled':''}>Check answer</button>`:`<button class="btn dark" id="nextq" ${a===undefined?'disabled':''}>${quiz.index===39?'Finish & review':'Next question →'}</button>`}</div><div class="questiondots" aria-label="Navegação pelas perguntas">${C.questions.map((q,i)=>`<button data-q="${i}" class="${quiz.answers[q.id]!==undefined?'answered':''} ${i===quiz.index?'current':''}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div><p class="mini">${Object.keys(quiz.answers).length}/40 answered. ${quiz.mode==='practice'?'Each answer locks after checking.':'Answers remain editable until you finish.'}</p><p id="quizmessage" role="status" class="mini"></p></section>`;}
function finish(){const missing=C.questions.findIndex(q=>quiz.answers[q.id]===undefined);if(missing!==-1){quiz.index=missing;render();toast('Responda a todas as perguntas antes de finalizar.');return;}quiz.finished=true;quiz.correct=C.questions.filter(q=>quiz.answers[q.id]===q.answer).length;quiz.seconds=Math.floor((Date.now()-quiz.start)/1000);state.attempts.push({mode:quiz.mode,correct:quiz.correct,score:Math.round(quiz.correct/40*100),seconds:quiz.seconds,date:new Date().toISOString()});save();render();}
function quizResults(){return `<section class="quizbox">${header('TENTATIVA CONCLUÍDA','Cada resposta é um próximo passo.','Reveja as explicações e regresse aos laboratórios para reforçar os conceitos.')}<div class="card"><span class="resultscore">${Math.round(quiz.correct/40*100)}%</span><h3>${quiz.correct} of 40 correct answers</h3><p class="sub">${Math.round(quiz.seconds/60)} minutos · ${quiz.correct>=32?'Meta didática atingida. Continue a validar os conceitos na prática.':'Reforce os tópicos abaixo e pratique novamente.'}</p><div class="quizactions"><a class="btn" href="#labs">Rever laboratórios</a><button class="btn dark" id="retryquiz">Nova tentativa →</button></div></div><h2>Answer review</h2>${C.questions.map(q=>`<div class="reviewitem"><strong>${quiz.answers[q.id]===q.answer?'✓':'○'} ${q.id}. ${esc(q.prompt)}</strong><small>Your answer: ${String.fromCharCode(65+quiz.answers[q.id])} · Correct: ${String.fromCharCode(65+q.answer)}</small>${esc(q.explanation)}</div>`).join('')}</section>`;}
function scenariosView(){let q=C.scenarios[scenario];return `<section class="quizbox scenario">${header('APLICAR O RACIOCÍNIO','Scenario practice','Write your reasoning, then compare it with the suggested answer. These questions are self-assessed.')}<div class="quiztop"><a class="link" href="#quiz">← Questionário</a><span>SCENARIO ${scenario+1} OF 10 · QUESTION ${q.id}</span></div><div class="reading">${markdown(q.prompt)}</div><label for="scenarioanswer" class="mini">YOUR RESPONSE</label><textarea id="scenarioanswer" placeholder="Explain your choices and reasoning…">${esc(state.scenarioNotes[q.id]||'')}</textarea><p class="mini">A resposta é guardada automaticamente neste navegador.</p>${reveal?`<div class="explain"><strong>Suggested answer</strong><p>${esc(q.answer)}</p><label><input type="checkbox" id="reviewed" ${state.scenarioReviewed.includes(q.id)?'checked':''}> I compared my response and reviewed the gaps.</label></div>`:'<button class="btn dark" id="revealscenario">Compare with suggested answer</button>'}<div class="quizactions"><button class="btn" id="prevscenario" ${scenario===0?'disabled':''}>← Previous</button><span class="mini">${state.scenarioReviewed.length}/10 reviewed</span><button class="btn" id="nextscenario" ${scenario===9?'disabled':''}>Next →</button></div></section>`;}
function render(){let route=location.hash.slice(1)||'home',nav=route.startsWith('lab')||route.startsWith('domain')?'labs':route.split('/')[0];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});let html;
if(route==='home')html=home();else if(route==='setup')html=header('ANTES DE COMEÇAR','Prepare o seu ambiente.','Starter original da Orders API: pré-requisitos, configuração e primeiros deployments.')+'<article class="reading">'+markdown(C.starter)+'</article><a class="btn dark" href="#labs">Seguir para os 20 laboratórios →</a>';else if(route==='labs'||route.startsWith('domain/')){if(route.startsWith('domain/'))domain=route.split('/')[1];html=labList();}else if(route.startsWith('lab/'))html=labDetail(+route.split('/')[1]);else if(route==='map')html=mapView();else if(route==='quiz/session')html=quizSession();else if(route==='quiz/scenarios')html=scenariosView();else if(route==='quiz')html=quizLanding();else html=home();$('#main').innerHTML=html;if(route==='home'||route==='labs')$('#main').insertAdjacentHTML('afterbegin','<div style="margin-bottom:20px"><a class="link" href="#setup">◎ Primeira vez? Configure o ambiente e consulte o starter →</a></div>');if($('#labresults')){filterLabs();$('#labsearch').oninput=e=>{search=e.target.value;filterLabs();};$('#domainfilter').onchange=e=>{domain=e.target.value;filterLabs();};$('#statusfilter').onchange=e=>{statusFilter=e.target.value;filterLabs();};}bind(route);updateSide();}
function bind(route){document.querySelectorAll('[data-map]').forEach(el=>{const go=()=>{mapId=el.dataset.map;render();};el.onclick=go;if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});document.querySelectorAll('.copybtn').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.previousElementSibling.textContent);b.textContent='Copiado';}catch{toast('Selecione o código para copiar.');}});
if($('#labstatus'))$('#labstatus').onchange=e=>{state.labs[+route.split('/')[1]]=e.target.value;save();toast('Progresso atualizado.');};if($('#bookmark'))$('#bookmark').onclick=()=>{let id=+route.split('/')[1];state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render();};
if($('#startpractice'))$('#startpractice').onclick=()=>startQuiz('practice');if($('#startexam'))$('#startexam').onclick=()=>startQuiz('exam');if($('#startscenarios'))$('#startscenarios').onclick=()=>location.hash='quiz/scenarios';if($('#retryquiz'))$('#retryquiz').onclick=()=>startQuiz(quiz.mode);
document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{quiz.answers[C.questions[quiz.index].id]=+b.dataset.option;render();});if($('#checkq'))$('#checkq').onclick=()=>{quiz.checked[C.questions[quiz.index].id]=true;render();};if($('#prevq'))$('#prevq').onclick=()=>{quiz.index--;render();};if($('#nextq'))$('#nextq').onclick=()=>{if(quiz.index===39)finish();else{quiz.index++;render();}};document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{quiz.index=+b.dataset.q;render();});
if($('#scenarioanswer'))$('#scenarioanswer').oninput=e=>{state.scenarioNotes[C.scenarios[scenario].id]=e.target.value;save();};if($('#revealscenario'))$('#revealscenario').onclick=()=>{reveal=true;render();};if($('#prevscenario'))$('#prevscenario').onclick=()=>{scenario--;reveal=false;render();};if($('#nextscenario'))$('#nextscenario').onclick=()=>{scenario++;reveal=false;render();};if($('#reviewed'))$('#reviewed').onchange=e=>{let id=C.scenarios[scenario].id;state.scenarioReviewed=e.target.checked?[...new Set([...state.scenarioReviewed,id])]:state.scenarioReviewed.filter(x=>x!==id);save();};}
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='az401-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#importfile').click();$('#importfile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const s=JSON.parse(await f.text());if(s.version!==1||!s.labs||!Array.isArray(s.bookmarks)||!Array.isArray(s.attempts)||!s.scenarioNotes||!Array.isArray(s.scenarioReviewed))throw Error();for(const [id,v]of Object.entries(s.labs))if(!C.labs.some(l=>String(l.id)===id)||!['done','progress','simulated','pending'].includes(v))throw Error();if(s.bookmarks.some(id=>!Number.isInteger(id)||id<1||id>20)||s.scenarioReviewed.some(id=>!Number.isInteger(id)||id<41||id>50)||s.attempts.some(a=>!['practice','exam'].includes(a.mode)||!Number.isFinite(a.score)||a.score<0||a.score>100||!Number.isFinite(a.correct)||!Number.isFinite(a.seconds)||Number.isNaN(Date.parse(a.date)))||Object.values(s.scenarioNotes).some(v=>typeof v!=='string'))throw Error();if(!confirm('Substituir o progresso deste navegador pelo ficheiro importado?'))return;state={labs:s.labs,bookmarks:s.bookmarks,attempts:s.attempts,scenarioNotes:s.scenarioNotes,scenarioReviewed:s.scenarioReviewed};save();render();toast('Progresso importado.');}catch{toast('Ficheiro de progresso inválido. Nada foi alterado.');}finally{e.target.value='';}};
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});setInterval(()=>{if($('#timer')&&quiz&&!quiz.finished)$('#timer').textContent=elapsed();},1000);render();

